        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","duration_minutes":150,"total_marks":221,"source":"myp-mock-myp4-mock","mock_exam_key":"myp4-mock","mock_code":"MYP4-MOCK-2026","sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":62,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":159,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
